CREATE OR REPLACE FUNCTION public.client_offboarding_assert_admin(p_tenant_id uuid)
 RETURNS void
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
  IF p_tenant_id IS DISTINCT FROM public.current_tenant_id() THEN
    RAISE EXCEPTION 'Mandant stimmt nicht mit der Sitzung überein.';
  END IF;
  IF NOT (public.is_tenant_admin() OR public.has_permission('office.clients.status_change')) THEN
    RAISE EXCEPTION 'Keine Berechtigung für Kündigung und Offboarding von Klient:innen.';
  END IF;
END;
$function$

CREATE OR REPLACE FUNCTION public.platform_has_capability(p_capability text)
 RETURNS boolean
 LANGUAGE plpgsql
 STABLE SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
DECLARE
  v_role TEXT;
BEGIN
  v_role := public.platform_current_role();
  IF v_role IS NULL THEN
    RETURN FALSE;
  END IF;

  -- Current product policy: no platform tariffs, add-ons or paid subscriptions.
  IF p_capability IN (
    'plans.read', 'plans.write', 'discounts.read', 'discounts.write',
    'billing.read', 'billing.write', 'payments.read', 'payments.write'
  ) THEN
    RETURN FALSE;
  END IF;

  IF v_role = 'platform_owner' THEN
    RETURN TRUE;
  END IF;

  CASE p_capability
    WHEN 'tenants.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_billing', 'platform_support',
        'platform_developer', 'platform_readonly'
      );
    WHEN 'tenants.write', 'tenants.suspend' THEN
      RETURN v_role = 'platform_admin';
    WHEN 'modules.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_support', 'platform_developer', 'platform_readonly'
      );
    WHEN 'modules.write' THEN
      RETURN v_role = 'platform_admin';
    WHEN 'plans.read', 'discounts.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_billing', 'platform_readonly'
      );
    WHEN 'plans.write', 'discounts.write' THEN
      RETURN v_role IN ('platform_admin', 'platform_billing');
    WHEN 'billing.read', 'payments.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_billing', 'platform_readonly'
      );
    WHEN 'billing.write', 'payments.write' THEN
      RETURN v_role IN ('platform_owner', 'platform_billing');
    WHEN 'flags.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_developer', 'platform_readonly'
      );
    WHEN 'flags.write' THEN
      RETURN v_role IN ('platform_owner', 'platform_developer');
    WHEN 'support.read', 'support.write' THEN
      RETURN v_role IN ('platform_owner', 'platform_admin', 'platform_support');
    WHEN 'audit.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_billing', 'platform_support',
        'platform_developer', 'platform_readonly'
      );
    WHEN 'system.read', 'releases.read' THEN
      RETURN v_role IN (
        'platform_admin', 'platform_developer', 'platform_readonly'
      );
    WHEN 'system.write' THEN
      RETURN v_role = 'platform_owner';
    WHEN 'users.read' THEN
      RETURN v_role IN ('platform_owner', 'platform_admin', 'platform_readonly');
    WHEN 'users.write' THEN
      RETURN v_role = 'platform_owner';
    ELSE
      RETURN FALSE;
  END CASE;
END;
$function$

CREATE OR REPLACE FUNCTION public.support_assert_access(p_request_id uuid, p_scope text)
 RETURNS support_access_requests
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE v_request public.support_access_requests%ROWTYPE; v_status text;
BEGIN
  SELECT * INTO v_request FROM public.support_access_requests WHERE id=p_request_id;
  IF NOT FOUND THEN RAISE EXCEPTION 'support_access_denied' USING ERRCODE='42501'; END IF;
  SELECT status INTO v_status FROM public.support_workspace_tickets WHERE id=v_request.ticket_id FOR UPDATE;
  SELECT * INTO v_request FROM public.support_access_requests WHERE id=p_request_id FOR UPDATE;
  IF auth.uid() IS NULL OR NOT public.platform_has_capability('support.write') OR v_status IN ('resolved','closed')
    OR v_request.status<>'approved' OR v_request.expires_at<=clock_timestamp() OR NOT (p_scope=ANY(v_request.scopes))
    OR NOT EXISTS(SELECT 1 FROM public.platform_users WHERE id=v_request.platform_user_id AND user_id=auth.uid() AND status='active')
  THEN RAISE EXCEPTION 'support_access_denied' USING ERRCODE='42501'; END IF;
  RETURN v_request;
END; $function$
